class OrderService {

    // Optimistic locking mac dinh (Product.version, xem Day 20 - day20-blk-55
    // va day20-blk-56) - da duoc Day 32 (day32-blk-18) chi dinh ap dung cho
    // dung buoc tru stock khi tao Order. day35-blk-6 chi ban muc isolation:
    // tu isolation KHONG du de chan lost update, phai them buoc khoa nay.
    @org.springframework.transaction.annotation.Transactional
    Order checkout(Long userId) {
        Cart cart = loadCart(userId);
        for (CartItem item : cart.getItems()) {
            reduceStock(item.getProductId(), item.getQuantity());
        }
        Order order = createOrderFromCart(cart);
        clearCart(cart);
        return order;
    }

    // Doc Product (co field @Version), tru stock trong bo nho, luu lai.
    // Hibernate dua version vao menh de WHERE cua cau UPDATE; neu transaction
    // khac da sua dong nay truoc (vi du checkout dong thoi cho cung san pham),
    // khong dong nao khop -> ObjectOptimisticLockingFailureException. KHONG tu
    // bat va lam lai ngam trong method nay - de exception thoat ra ngoai lam
    // @Transactional cua checkout() rollback toan bo (Order khong duoc tao,
    // Cart khong bi xoa), tra loi loi cho client de nguoi dung tu bam lai.
    private void reduceStock(Long productId, int quantity) {
        Product product = productRepository.findById(productId)
                .orElseThrow(() -> new IllegalArgumentException("San pham khong ton tai"));
        if (product.getStock() < quantity) {
            throw new IllegalStateException("Khong du ton kho");
        }
        product.setStock(product.getStock() - quantity);
        productRepository.save(product);
    }

    private Cart loadCart(Long userId) { return null; }
    private Order createOrderFromCart(Cart cart) { return null; }
    private void clearCart(Cart cart) { }
}

class OrderController {

    // Doc chu so huu tu JWT giong het day34-blk-17 (CartController), KHONG
    // nhan userId tu path/body.
    @org.springframework.web.bind.annotation.GetMapping("/api/orders/{id}")
    OrderDto getOrder(@org.springframework.web.bind.annotation.PathVariable Long id,
                       org.springframework.security.core.Authentication authentication) {
        Long currentUserId = Long.valueOf(
            ((org.springframework.security.oauth2.jwt.Jwt) authentication.getPrincipal()).getSubject());

        Order order = orderRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Khong tim thay order"));

        // So khop chu so huu TRUOC khi tra du lieu - thieu buoc nay se lo don
        // hang cua nguoi khac cho bat ky user da dang nhap nao doan duoc id
        // (xem day35-blk-33 ve ly do va co che tao 403).
        if (!order.getUserId().equals(currentUserId)) {
            throw new org.springframework.security.access.AccessDeniedException(
                "Order khong thuoc ve user hien tai");
        }

        return toDto(order);
    }

    // GET /api/orders (danh sach) tu loc theo currentUserId giong CartController
    // (day34-blk-17), khong can buoc so khop chu so huu vi khong nhan id tren path.

    private OrderDto toDto(Order order) { return null; }
}

