import java.io.PrintWriter;
import java.util.List;
import java.util.stream.Collectors;

class OrderCsvExporter {

    void writeCsv(PrintWriter writer, List<Order> orders) {
        for (Order order : orders) {
            String[] row = { String.valueOf(order.getId()), order.getStatus(), String.valueOf(order.getTotal()) };
            writer.println(convertToCsvRow(row));
        }
    }

    private String convertToCsvRow(String[] fields) {
        return java.util.Arrays.stream(fields)
                .map(this::escapeSpecialCharacters)
                .collect(Collectors.joining(","));
    }

    private String escapeSpecialCharacters(String field) {
        String escaped = field.replace("\n", " ");
        if (escaped.contains(",") || escaped.contains("\"")) {
            escaped = "\"" + escaped.replace("\"", "\"\"") + "\"";
        }
        return escaped;
    }
}

